mod support;
use std::path::Path;use sha2::{Digest,Sha256};use tokio_util::sync::CancellationToken;
use video_kadr_backend::{services::{concat_video_analysis::{RunCache,import_checkpoint},concat_video_checkpoint::Expected},domain::{group_surface::GroupSurface,concat_cutout_mask::{self,MaskPlane},concat_picture::Preparation}};
const MODEL:&str="88d4531297118f595bf2fd60f6f566aec2e559393802d1f436c380f0cbbd2828";
fn hash(bytes:&[u8])->String{format!("{:x}",Sha256::digest(bytes))}
fn file(path:&Path,bytes:&[u8]){std::fs::write(path,bytes).unwrap();#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::set_permissions(path,std::fs::Permissions::from_mode(0o600)).unwrap();}}
fn directory(path:&Path){std::fs::create_dir(path).unwrap();#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::set_permissions(path,std::fs::Permissions::from_mode(0o700)).unwrap();}}
fn pixels()->Vec<u8>{[70u8,90,110,255].repeat(32*16)}
fn plane(blank:bool)->Vec<u8>{(0..512*256).map(|index|if !blank&&index%512>=256{255}else{0}).collect()}
async fn cache(root:&Path,video:&str,blank:bool)->RunCache{
 let checkpoint=root.join("checkpoints");directory(&checkpoint);let frame=checkpoint.join("0");directory(&frame);let source=pixels();let mask=plane(blank);let mut rgba=source.clone();if !blank{for y in 0..16{for x in 0..16{rgba[(y*32+x)*4+3]=0;}}}let sequence=hash(&source);let runtime="b".repeat(64);file(&frame.join("frame.rgba"),&rgba);file(&frame.join("mask.raw"),&mask);let receipt=serde_json::json!({"schemaVersion":1,"ordinal":0,"context":{"sourceHash":sequence,"frameHash":sequence,"modelHash":MODEL,"runtimeHash":runtime,"width":32,"height":16,"maskWidth":512,"maskHeight":256,"total":1},"outputHash":hash(&rgba),"maskHash":hash(&mask),"blank":blank});file(&frame.join("receipt.json"),&serde_json::to_vec(&receipt).unwrap());let cancel=CancellationToken::new();let run=import_checkpoint(&checkpoint,Expected{sequence_hash:&sequence,model_hash:MODEL,runtime_hash:&runtime,source_frame:&source,width:32,height:16,ordinal:0,total:1},video,0,root,&cancel,std::time::Duration::from_secs(10)).await.unwrap();let mut cache=RunCache::new(video.into(),runtime).unwrap();cache.insert(run).unwrap();cache
}
fn expected(feather:f64)->GroupSurface{
 let input=video_kadr_mask_core::Mask{width:512,height:256,bytes:plane(false)};let mask=video_kadr_mask_core::mask_edit::feather(&input,feather as f32*512.,&std::sync::atomic::AtomicBool::new(false)).unwrap();let mut frame=GroupSurface{width:32,height:16,rgba:pixels()};concat_cutout_mask::apply(&mut frame,MaskPlane{width:512,height:256,probabilities:&mask.bytes},&Preparation{crop:[0.;4],canvas:[32,16],flip_h:false,flip_v:false},&mut||Ok(())).unwrap();frame
}
#[tokio::test]
async fn video_feather_softens_both_sides_without_reanalysis_or_changing_rgb(){
 let root=tempfile::tempdir().unwrap();let mut cache=cache(root.path(),&"a".repeat(64),false).await;let identity=cache.identity().unwrap();let cancel=CancellationToken::new();let original=GroupSurface{width:32,height:16,rgba:pixels()};let mut legacy=original.clone();cache.apply_decoded(&mut legacy,0,&cancel).unwrap();assert_eq!(legacy,expected(0.));let mut soft=original.clone();cache.apply_decoded_with_feather(&mut soft,0,0.1,&cancel).unwrap();assert_eq!(soft,expected(0.1));assert_ne!(soft,legacy);assert!((0..16).any(|x|soft.rgba[x*4+3]>0));assert!((16..32).any(|x|soft.rgba[x*4+3]<255));for(actual,input)in soft.rgba.chunks_exact(4).zip(original.rgba.chunks_exact(4)){assert_eq!(actual[..3],input[..3]);}assert_eq!(cache.identity().unwrap(),identity);
 for value in [-0.001,0.101,f64::NAN,f64::INFINITY]{let mut frame=original.clone();assert!(cache.apply_decoded_with_feather(&mut frame,0,value,&cancel).is_err());assert_eq!(frame,original);}
 let blank_root=tempfile::tempdir().unwrap();let mut blank=crate::cache(blank_root.path(),&"a".repeat(64),true).await;let mut frame=original.clone();blank.apply_decoded_with_feather(&mut frame,0,0.1,&cancel).unwrap();assert_eq!(frame,original);
 let wire=serde_json::json!({"subject":"person","sourceHash":"a".repeat(64),"modelHash":MODEL,"runtimeHash":"b".repeat(64)});let legacy:video_kadr_backend::domain::concat_video_binding::Binding=serde_json::from_value(wire.clone()).unwrap();assert!(legacy.feather.is_none());assert_eq!(serde_json::to_value(legacy).unwrap(),wire);for invalid in [-0.001,0.101]{let mut wrong=wire.clone();wrong["feather"]=serde_json::json!(invalid);assert!(serde_json::from_value::<video_kadr_backend::domain::concat_video_binding::Binding>(wrong).is_err());}
}
