#[tokio::test]
async fn authored_video_strokes_preserve_blank_custom_intent_and_raw_cache(){
 use video_kadr_backend::domain::cutout::{Correction,Stroke,Tool};
 let root=tempfile::tempdir().unwrap();let mut cache=cache(root.path(),&"a".repeat(64),true).await;let identity=cache.identity().unwrap();let cancel=CancellationToken::new();
 let original=GroupSurface{width:32,height:16,rgba:pixels()};
 for tool in [Tool::Brush,Tool::Eraser,Tool::SmartBrush,Tool::SmartEraser]{
  let correction=Correction{custom:true,feather:0.,strokes:vec![Stroke{tool,size:0.25,points:vec![[0.5,0.5]],at:None,region:None}]};
  let mut actual=original.clone();let dispatch=cache.apply_decoded_with_correction(&mut actual,0,&correction,&cancel).unwrap();assert!(matches!(dispatch,video_kadr_backend::domain::concat_cutout_clock::Dispatch::Applied{..}));
  let automatic=video_kadr_backend::domain::concat_cutout_clock::ResolvedMask{width:512,height:256,probabilities:plane(true)};
  let plan=video_kadr_backend::domain::concat_cutout_import::Plan{subject:video_kadr_backend::domain::concat_cutout_import::Subject::Auto,correction,region_source_seconds:vec![]};
  let resolved=video_kadr_backend::domain::concat_cutout_resolve::resolve(&plan,&automatic,&[],2.,&std::sync::atomic::AtomicBool::new(false)).unwrap().unwrap();
  let mut expected=original.clone();concat_cutout_mask::apply(&mut expected,MaskPlane{width:512,height:256,probabilities:&resolved.probabilities},&Preparation{crop:[0.;4],canvas:[32,16],flip_h:false,flip_v:false},&mut||Ok(())).unwrap();assert_eq!(actual,expected);assert_ne!(actual,original);
 }
 assert_eq!(cache.identity().unwrap(),identity);let mut automatic=original.clone();cache.apply_decoded(&mut automatic,0,&cancel).unwrap();assert_eq!(automatic,original);
}

#[test]
fn saved_video_corrections_roundtrip_and_reject_ambiguous_settings(){
 let correction=serde_json::json!({"custom":true,"feather":0.01,"strokes":[{"tool":"brush","size":0.1,"points":[[0.25,0.5]]}]});
 let mut wire=serde_json::json!({"subject":"person","sourceHash":"a".repeat(64),"modelHash":MODEL,"runtimeHash":"b".repeat(64),"correction":correction});
 let binding:video_kadr_backend::domain::concat_video_binding::Binding=serde_json::from_value(wire.clone()).unwrap();assert!(binding.settings().custom);assert_eq!(binding.settings().strokes.len(),1);assert_eq!(binding.settings().feather,0.01);
 let encoded=serde_json::to_value(&binding).unwrap();let restored:video_kadr_backend::domain::concat_video_binding::Binding=serde_json::from_value(encoded).unwrap();assert_eq!(binding,restored);
 wire["feather"]=serde_json::json!(0.02);assert!(serde_json::from_value::<video_kadr_backend::domain::concat_video_binding::Binding>(wire.clone()).is_err());wire["feather"]=serde_json::json!(0.01);wire["correction"]["strokes"][0]["tool"]=serde_json::json!("smartBrush");wire["correction"]["strokes"][0]["at"]=serde_json::json!(0);assert!(serde_json::from_value::<video_kadr_backend::domain::concat_video_binding::Binding>(wire).is_err());
}

#[tokio::test]
async fn timed_smart_video_regions_follow_each_frame_and_reject_wrong_source_clock(){
 use video_kadr_backend::{domain::{cutout::{Correction,Stroke,Tool},concat_cutout_clock::{ResolvedMask,Dispatch}},services::concat_video_analysis::SourceRegions};
 let root=tempfile::tempdir().unwrap();let video="a".repeat(64);let mut cache=cache(root.path(),&video,true).await;let cancel=CancellationToken::new();let original=GroupSurface{width:32,height:16,rgba:pixels()};
 let correction=Correction{custom:true,feather:0.,strokes:vec![Stroke{tool:Tool::SmartBrush,size:0.005,points:vec![[0.25,0.5]],at:Some(0.),region:None}]};
 let right=plane(false);let left=right.iter().map(|v|255-v).collect::<Vec<_>>();
 let mut results=vec![];
 for(time,plane)in [(0,left),(10000,right),(20000,plane(true))]{
  let regions=SourceRegions{video_hash:video.clone(),source_us:time,planes:vec![Some(std::sync::Arc::new(ResolvedMask{width:512,height:256,probabilities:plane}))]};
  let mut frame=original.clone();assert!(matches!(cache.apply_decoded_with_regions(&mut frame,time,&correction,Some(&regions),&cancel).unwrap(),Dispatch::Applied{..}));results.push(frame);
 }
 for y in 0..16{for x in 0..32{assert_eq!(results[0].rgba[(y*32+x)*4+3],if x<16{255}else{0});assert_eq!(results[1].rgba[(y*32+x)*4+3],if x>=16{255}else{0});assert_eq!(results[2].rgba[(y*32+x)*4+3],0);}}
 let eraser_root=tempfile::tempdir().unwrap();let mut eraser_cache=crate::cache(eraser_root.path(),&video,false).await;let mut eraser=correction.clone();eraser.strokes[0].tool=Tool::SmartEraser;
 let regions=SourceRegions{video_hash:video.clone(),source_us:0,planes:vec![Some(std::sync::Arc::new(ResolvedMask{width:512,height:256,probabilities:plane(false)}))]};let mut erased=original.clone();eraser_cache.apply_decoded_with_regions(&mut erased,0,&eraser,Some(&regions),&cancel).unwrap();assert!(erased.rgba.chunks_exact(4).all(|p|p[3]==0));
 for region in [SourceRegions{video_hash:"b".repeat(64),source_us:0,planes:vec![None]},SourceRegions{video_hash:video.clone(),source_us:1,planes:vec![None]},SourceRegions{video_hash:video.clone(),source_us:0,planes:vec![]},SourceRegions{video_hash:video.clone(),source_us:0,planes:vec![None]}]{let mut frame=original.clone();assert!(cache.apply_decoded_with_regions(&mut frame,0,&correction,Some(&region),&cancel).is_err());assert_eq!(frame,original);}
 let mut frame=original.clone();assert!(cache.apply_decoded_with_correction(&mut frame,0,&correction,&cancel).is_err());assert_eq!(frame,original);
}
